<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$lab=getenv('IMPE_PHONE_LAB_ROOT');
if(!is_string($lab)||!is_file($lab.'/credentials.json'))throw new RuntimeException('Set the private synthetic laboratory path.');
$c=json_decode(file_get_contents($lab.'/credentials.json'),true,32,JSON_THROW_ON_ERROR);
if($c['host']!=='127.0.0.1'||$c['port']!==3308||$c['database']!=='impe_telefonia_lab')throw new RuntimeException('Wrong synthetic target');
date_default_timezone_set('America/Mexico_City');
require_once $lab.'/site/config/db_connection.php';
require_once $lab.'/site/app/services/TelefoniaSesionLocalService.php';
$db=Database::compartida();
if($db->query('SELECT DATABASE() n')->fetch_assoc()['n']!=='impe_telefonia_lab')throw new RuntimeException('Wrong fixture database');
$service=new TelefoniaSesionLocalService($db);$checks=0;
$assert=static function(bool $value,string $why)use(&$checks){if(!$value)throw new RuntimeException($why);$checks++;};
$rejected=static function(callable $fn,string $why)use($assert){$caught=false;try{$fn();}catch(DomainException|InvalidArgumentException $e){$caught=true;}$assert($caught,$why);};
$id='sdk-'.bin2hex(random_bytes(16));$ref='fixture-link-'.bin2hex(random_bytes(8));
$base=['session_id'=>$id,'direccion'=>'ENTRANTE','numero'=>'100','sdk_id'=>'fixture-link-sip'];
foreach(['ringing','answered','ended'] as $n=>$kind)$service->registrarEvento(42,$base+['evento'=>$kind,'secuencia'=>$n+1],2);
$original=$service->obtener(42,$id);$marker=(int)$db->query('SELECT COALESCE(MAX(id),0) n FROM telefonia_zadarma_eventos')->fetch_assoc()['n'];
$s=$db->prepare("INSERT INTO telefonia_transferencia_operaciones(origen_usuario,origen_extension,destino_usuario,destino_extension,referencia,numero,modo,estado,evento_desde,sdk_consulta,created_at,updated_at) VALUES(43,'100',42,'102',?,'5550000000','DIRECTA','ENTREGADA',?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())");
$s->bind_param('sis',$ref,$marker,$id);$s->execute();$op=(int)$s->insert_id;$s->close();
$event=$base+['evento'=>'transfer_link','secuencia'=>4,'operacion_id'=>$op,'intento'=>1];
$rejected(fn()=>$service->registrarEvento(42,$event,2),'No own PBX answer cannot link');
$assert((int)$service->obtener(42,$id)['ultima_secuencia']===3,'Rejected evidence leaves sequence untouched');
$seed=static function(string $reference,string $ext,?string $at=null)use($db){$at??=date('Y-m-d H:i:s');$s=$db->prepare("INSERT INTO telefonia_zadarma_eventos(pbx_call_id,evento,internal,received_at,call_start,payload_json) VALUES(?,'NOTIFY_ANSWER',?,?,?,'{}')");$s->bind_param('ssss',$reference,$ext,$at,$at);$s->execute();$event=(int)$s->insert_id;$s->close();return $event;};
$seed($ref,'100');$rejected(fn()=>$service->registrarEvento(42,$event,2),'Source answer cannot link recipient');
$seed(strtoupper($ref),'102');$rejected(fn()=>$service->registrarEvento(42,$event,2),'PBX reference is case sensitive');
$seed($ref,'102','2010-01-01 00:00:00');$rejected(fn()=>$service->registrarEvento(42,$event,2),'Previous assignment answer cannot link');
$answer=$seed($ref,'102');
$rejected(fn()=>$service->registrarEvento(42,array_replace($event,['intento'=>2]),2),'Another attempt cannot link');
$rejected(fn()=>$service->registrarEvento(41,$event,2),'Another user cannot link');
$db->query("UPDATE telefonia_transferencia_operaciones SET estado='CONSULTANDO' WHERE id=$op");
$rejected(fn()=>$service->registrarEvento(42,$event,2),'Consultation is not delivered customer');
$db->query("UPDATE telefonia_transferencia_operaciones SET estado='ENTREGADA',sdk_consulta='sdk-another-physical-dialogue' WHERE id=$op");
$rejected(fn()=>$service->registrarEvento(42,$event,2),'Different physical SDK cannot link');
$s=$db->prepare('UPDATE telefonia_transferencia_operaciones SET sdk_consulta=? WHERE id=?');$s->bind_param('si',$id,$op);$s->execute();$s->close();
$service->registrarEvento(42,$event,2);$row=$service->obtener(42,$id);
$assert($row['pbx_call_id']===$ref&&(int)$row['pbx_inicio_evento']===$answer,'Exact delivered operation binds own answer event');
$assert($row['estado']===$original['estado']&&$row['fecha_fin']===$original['fecha_fin'],'Late PBX evidence does not reopen transport');
$assert($row['clasificacion']===$original['clasificacion']&&$row['interaccion_id']===$original['interaccion_id'],'Binding does not invent or rewrite business result');
$service->registrarEvento(42,$event,2);$assert((int)$service->obtener(42,$id)['ultima_secuencia']===4,'Lost ACK replay idempotent');
$rejected(fn()=>$service->registrarEvento(42,array_replace($event,['operacion_id'=>$op+1]),2),'Same sequence different operation rejected');
echo "PASS $checks exact transfer/SDK/PBX binding SQL checks; synthetic data only.\n";
